 use serde :: { Deserialize , Serialize } ; use std :: collections :: HashMap ; # [doc = " Attempts to resolve the actual crate path within a submodule directory."] # [doc = " This handles cases where the [workspace.dependencies.<name>].path points to a submodule root,"] # [doc = " but the actual crate (with its Cargo.toml) resides in a subdirectory."] # [doc = " It prioritizes subdirectories named after the crate, then performs a shallow search."] pub fn resolve_crate_path_in_submodule (submodule_path : & Path , crate_name : & str) -> Result < PathBuf > { if submodule_path . join ("Cargo.toml") . exists () { return Ok (submodule_path . to_path_buf ()) ; } let named_subdir_path = submodule_path . join (crate_name . replace ('-' , "_")) ; if named_subdir_path . join ("Cargo.toml") . exists () { return Ok (named_subdir_path) ; } let named_subdir_path_kebab = submodule_path . join (crate_name) ; if named_subdir_path_kebab . join ("Cargo.toml") . exists () { return Ok (named_subdir_path_kebab) ; } for entry in WalkDir :: new (submodule_path) . max_depth (2) . into_iter () . filter_map (| e | e . ok ()) { if entry . file_name () == "Cargo.toml" { let cargo_toml_path = entry . path () ; let parent_dir = cargo_toml_path . parent () . context ("Cargo.toml has no parent") ? ; if parent_dir != submodule_path { return Ok (parent_dir . to_path_buf ()) ; } } } Ok (submodule_path . to_path_buf ()) }